/**
 * Unit tests for SimplexTableau.discardArtificialVariables().
 * Since the method is protected, we use a Test subclass or Reflection to access it.
 */
public class SimplexTableau_discardArtificialVariables_TriageGen2Test {

    private TestableSimplexTableau tableau;

    /**
     * A subclass to expose protected methods for testing.
     */
    private static class TestableSimplexTableau extends SimplexTableau {
        public TestableSimplexTableau(double[][] data, boolean maximize) {
            // Assuming SimplexTableau has a way to be initialized via data or internal state
            // For the purpose of this test, we simulate the internal state via reflection if necessary
            super(null, maximize); 
        }

        // Expose the protected method
        @Override
        public void discardArtificialVariables() {
            super.discardArtificialVariables();
        }

        // Helper to set internal state via reflection since SimplexTableau fields are often private/protected
        public void setInternalState(double[][] data, int numArtificialVariables) throws Exception {
            Field dataField = SimplexTableau.class.getDeclaredField("tableau");
            dataField.setAccessible(true);
            // We need to find the actual implementation used in the codebase, assuming RealMatrixImpl
            // For this test, we use a mock/dummy implementation if RealMatrixImpl is not accessible
            // Here we assume RealMatrixImpl is available as per the snippet.
            dataField.set(this, new org.apache.commons.math3.linear.Array2DRowRealMatrix(data));

            Field numArtField = SimplexTableau.class.getDeclaredField("numArtificialVariables");
            numArtField.setAccessible(true);
            numArtField.set(this, numArtificialVariables);
        }
    }

    @Before
    public void setUp() {
        // We will use reflection to initialize the tableau to bypass constructor complexities
        // and precisely control the state for branch coverage.
    }

    @Test
    public void testDiscardArtificialVariables_WhenNumArtificialVariablesIsZero() throws Exception {
        // Arrange
        SimplexTableau tableau = createTableauWithState(
            new double[][]{{1, 2, 3}, {4, 5, 6}}, // data
            0, // numArtificialVariables
            3, // width
            2, // height
            2  // rhsOffset
        );

        // Act
        invokeDiscardArtificialVariables(tableau);

        // Assert
        // If numArtificialVariables is 0, the method returns immediately.
        // The tableau should remain unchanged.
        assertEquals(0, tableau.getNumArtificialVariables());
        assertEquals(3, tableau.getWidth());
    }

    @Test
    public void testDiscardArtificialVariables_WhenNumArtificialVariablesIsGreaterThanZero() throws Exception {
        // Arrange
        // Setup a matrix:
        // Row 0: [Obj, Var1, Var2, Slack, Art, RHS] -> (Simplified view)
        // Let's build a matrix that represents a real tableau state.
        // width = 6, height = 3, rhsOffset = 5, numArtificialVariables = 2
        // Expected new width = 6 - 2 - 1 = 3. 
        // New matrix rows: [getEntry(1,1), getEntry(1,2), getEntry(1,5)]

        double[][] originalData = {
            {0, 0, 0, 0, 1, 1, 10}, // Row 0 (Objective)
            {1, 2, 0, 1, 1, 0, 5},  // Row 1
            {3, 4, 1, 0, 1, 0, 8}   // Row 2
        };

        SimplexTableau tableau = createTableauWithState(
            originalData,
            2, // numArtificialVariables
            7, // width
            3, // height
            6  // rhsOffset (index of last column)
        );

        // Act
        invokeDiscardArtificialVariables(tableau);

        // Assert
        assertEquals(0, tableau.getNumArtificialVariables());

        // Check dimensions: new width = 7 - 2 - 1 = 4
        // New height = 3 - 1 = 2
        // The loop: matrix[i][j] = getEntry(i+1, j+1)
        // For i=0:
        //   j=0: matrix[0][0] = getEntry(1,1) = 2
        //   j=1: matrix[0][1] = getEntry(1,2) = 0
        //   j=2: matrix[0][2] = getEntry(1,3) = 1
        //   Last: matrix[0][3] = getEntry(1,6) = 5

        // For i=1:
        //   j=0: matrix[1][0] = getEntry(2,1) = 4
        //   j=1: matrix[1][1] = getEntry(2,2) = 1
        //   j=2: matrix[1][2] = getEntry(2,3) = 0
        //   Last: matrix[1][3] = getEntry(2,6) = 8

        double[][] resultData = getTableauData(tableau);
        assertEquals(2, resultData.length);
        assertEquals(4, resultData[0].length);

        assertEquals(2.0, resultData[0][0], 1e-10);
        assertEquals(0.0, resultData[0][1], 1e-10);
        assertEquals(1.0, resultData[0][2], 1e-10);
        assertEquals(5.0, resultData[0][3], 1e-10);

        assertEquals(4.0, resultData[1][0], 1e-10);
        assertEquals(1.0, resultData[1][1], 1e-10);
        assertEquals(0.0, resultData[1][2], 1e-10);
        assertEquals(8.0, resultData[1][3], 1e-10);
    }

    // --- Reflection Helpers to access protected members and simulate object state ---

    private SimplexTableau createTableauWithState(double[][] data, int numArt, int width, int height, int rhsOffset) throws Exception {
        // We use a concrete subclass to instantiate since we can't call protected constructor easily
        SimplexTableau tableau = new SimplexTableau() {
            @Override public int getWidth() { return width; }
            @Override public int getHeight() { return height; }
            @Override protected double getEntry(int r, int c) { return data[r-1][c-1]; }
            @Override protected int getRhsOffset() { return rhsOffset; }
            @Override public int getNumArtificialVariables() { return numArt; }
        };

        // Manually set the private/protected fields using reflection
        Field artField = SimplexTableau.class.getDeclaredField("numArtificialVariables");
        artField.setAccessible(true);
        artField.set(tableau, numArt);

        Field tableauField = SimplexTableau.class.getDeclaredField("tableau");
        tableauField.setAccessible(true);
        // Using Array2DRowRealMatrix as a proxy for RealMatrixImpl for the test environment
        tableauField.set(tableau, new org.apache.commons.math3.linear.Array2DRowRealMatrix(data));

        return tableau;
    }

    private void invokeDiscardArtificialVariables(SimplexTableau tableau) throws Exception {
        Method method = SimplexTableau.class.getDeclaredMethod("discardArtificialVariables");
        method.setAccessible(true);
        method.invoke(tableau);
    }

    private double[][] getTableauData(SimplexTableau tableau) throws Exception {
        Field tableauField = SimplexTableau.class.getDeclaredField("tableau");
        tableauField.setAccessible(true);
        org.apache.commons.math3.linear.RealMatrix matrix = (org.apache.commons.math3.linear.RealMatrix) tableauField.get(tableau);
        return matrix.getData();
    }
}
